@@ -0,0 +1,15 @@
+import { createEventCard } from "./event-card.js";
+
+export function sortByStart(events, project = createEventCard) {
+  return events
+    .map((event) => {
+      const value = project(event);
+      return { value, time: new Date(event.startsAt).getTime() };
+    })
+    .sort((a, b) => a.time - b.time)
+    .map(({ value }) => value);
+}
+
+export function buildAgenda(events) {
+  return sortByStart(events, createEventCard);
+}

